from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self):super().__init__();self.skip=0;self.lines=[]
 def handle_starttag(self,t,a):
  if t in ['script','style']:self.skip+=1
  if t=='a' and not self.skip:self.lines.append('LINK '+str(dict(a).get('href')))
 def handle_endtag(self,t):
  if t in ['script','style']:self.skip-=1
 def handle_data(self,d):
  if not self.skip and d.strip():self.lines.append(d.strip())
p=P();p.feed(open('products/services/new-actionable-buyers/canadian-project.html').read());print('\n'.join(p.lines)[-16000:])
